node -e "
function formatAmount(cents) {
  const units = Math.trunc(cents / 100);
  const rest = Math.abs(cents % 100);
  return \`\${units.toLocaleString('de-DE')},\${String(rest).padStart(2, '0')} EUR\`;
}
console.log(formatAmount(123456789));
